<?php
class PlanillaModel {
private $db; public function __construct(PDO $db){$this->db=$db;}
public function datos():array{return ['personas'=>$this->db->query("SELECT p.id_persona,p.nombres,p.apellidos,GROUP_CONCAT(pp.tipo) perfiles FROM personas p JOIN persona_perfiles pp ON pp.id_persona=p.id_persona AND pp.estado='ACTIVO' LEFT JOIN vinculos_laborales v ON v.id_persona=p.id_persona AND v.estado='ACTIVO' WHERE p.estado='ACTIVO' AND v.id_vinculo IS NULL AND pp.tipo IN('DOCENTE','ADMINISTRATIVO') GROUP BY p.id_persona ORDER BY p.apellidos")->fetchAll(),'vinculos'=>$this->db->query("SELECT v.*,CONCAT(p.apellidos,', ',p.nombres) persona FROM vinculos_laborales v JOIN personas p ON p.id_persona=v.id_persona ORDER BY v.estado='ACTIVO' DESC,p.apellidos")->fetchAll(),'periodos'=>$this->db->query("SELECT * FROM periodos_pago ORDER BY fecha_inicio DESC")->fetchAll()];}
public function vinculo(array $d):void{$s=$this->db->prepare("INSERT INTO vinculos_laborales(id_persona,tipo,modalidad_pago,monto_base,fecha_inicio,fecha_fin,estado) VALUES(?,?,?,?,?,?,'ACTIVO')");$s->execute([(int)$d['id_persona'],$d['tipo'],$d['modalidad_pago'],(float)$d['monto_base'],$d['fecha_inicio'],$d['fecha_fin']?:null]);}
public function periodo(array $d):void{$s=$this->db->prepare("INSERT INTO periodos_pago(nombre,fecha_inicio,fecha_fin,estado) VALUES(?,?,?,'ABIERTO')");$s->execute([trim($d['nombre']),$d['fecha_inicio'],$d['fecha_fin']]);}
public function calcular(int $id):int{$this->db->beginTransaction();try{$q=$this->db->prepare("SELECT v.id_vinculo,v.monto_base FROM vinculos_laborales v WHERE v.estado='ACTIVO' AND v.fecha_inicio<=(SELECT fecha_fin FROM periodos_pago WHERE id_periodo_pago=?) AND (v.fecha_fin IS NULL OR v.fecha_fin>=(SELECT fecha_inicio FROM periodos_pago WHERE id_periodo_pago=?))");$q->execute([$id,$id]);$i=$this->db->prepare("INSERT INTO planilla_detalles(id_periodo_pago,id_vinculo,monto_base,bonificaciones,descuentos,monto_pagar,estado) VALUES(?,?,?,0,0,?,'CALCULADO') ON DUPLICATE KEY UPDATE monto_base=VALUES(monto_base),monto_pagar=VALUES(monto_pagar),calculado_en=NOW()");$n=0;foreach($q->fetchAll() as $v){$i->execute([$id,$v['id_vinculo'],$v['monto_base'],$v['monto_base']]);$n+=$i->rowCount();}$this->db->prepare("UPDATE periodos_pago SET estado='CALCULADO' WHERE id_periodo_pago=?")->execute([$id]);$this->db->commit();return $n;}catch(Throwable $e){$this->db->rollBack();throw $e;}}
}
